import{_ as d,o as e,c as a,a3 as o}from"./chunks/framework.qCVWde4n.js";const g=JSON.parse('{"title":"多语言与界面文本","description":"","frontmatter":{},"headers":[],"relativePath":"features/i18n.md","filePath":"features/i18n.md","lastUpdated":null}'),r={name:"features/i18n.md"};function s(n,t,i,l,c,h){return e(),a("div",null,[...t[0]||(t[0]=[o(`<h1 id="多语言与界面文本" tabindex="-1">多语言与界面文本 <a class="header-anchor" href="#多语言与界面文本" aria-label="Permalink to &quot;多语言与界面文本&quot;">​</a></h1><p>因为是在汉化版基础上做的，界面已经是中文。本篇说明<strong>文本是怎么改的</strong>、以及<strong>为什么有些英文不能翻</strong>。</p><h2 id="现状" tabindex="-1">现状 <a class="header-anchor" href="#现状" aria-label="Permalink to &quot;现状&quot;">​</a></h2><table tabindex="0"><thead><tr><th>层</th><th>内容</th><th>改在哪</th></tr></thead><tbody><tr><td><strong>界面文本</strong></td><td>按钮、菜单、提示</td><td>游戏资源文件</td></tr><tr><td><strong>运行时文本</strong></td><td>战斗中的动态提示、舰船名</td><td>DLL 的字符串堆</td></tr><tr><td><strong>框架自身界面</strong></td><td>控制台六个页面</td><td>框架代码（本来就是中文）</td></tr></tbody></table><h2 id="双层机制-为什么有的文本要改两个地方" tabindex="-1">双层机制：为什么有的文本要改两个地方 <a class="header-anchor" href="#双层机制-为什么有的文本要改两个地方" aria-label="Permalink to &quot;双层机制：为什么有的文本要改两个地方&quot;">​</a></h2><div class="tip custom-block"><p class="custom-block-title">这是汉化最容易搞错的一点</p><p>游戏内的文本分布在<strong>两个不同的地方</strong>：</p><ol><li><strong>静态文本</strong> —— 存在资源文件里（菜单、界面标签）</li><li><strong>运行时文本</strong> —— 存在 DLL 里（代码里写死的提示语）</li></ol><p>改错地方 = 改了没效果。所以汉化必须<strong>两层都覆盖</strong>。</p></div><h3 id="资源层" tabindex="-1">资源层 <a class="header-anchor" href="#资源层" aria-label="Permalink to &quot;资源层&quot;">​</a></h3><p>游戏把静态文本打包在 <code>level0</code> / <code>sharedassets*.assets</code> 里。要改这些，需要解析序列化文件并写回。</p><h3 id="dll-层" tabindex="-1">DLL 层 <a class="header-anchor" href="#dll-层" aria-label="Permalink to &quot;DLL 层&quot;">​</a></h3><p>代码里写死的文本在 <code>Assembly-CSharp.dll</code> 的字符串堆里：</p><table tabindex="0"><thead><tr><th>堆</th><th>编码</th><th>存什么</th></tr></thead><tbody><tr><td><code>#US</code>（User Strings）</td><td><strong>UTF-16</strong>（每字符 2 字节）</td><td>用户可见的字符串</td></tr><tr><td><code>#Strings</code></td><td><strong>UTF-8</strong></td><td>类型名、方法名、字段名</td></tr></tbody></table><div class="warning custom-block"><p class="custom-block-title">字节搜索必须分清编码</p><p>用 UTF-8 去搜 <code>#US</code> 堆里的中文，<strong>一定搜不到</strong> —— 那是假阴性（实际存在但搜不到），不是真的没写进去。</p><p>这是汉化过程中最容易得出的错误结论。</p></div><h2 id="关键规则-哪些英文绝对不能翻" tabindex="-1">关键规则：哪些英文绝对不能翻 <a class="header-anchor" href="#关键规则-哪些英文绝对不能翻" aria-label="Permalink to &quot;关键规则：哪些英文绝对不能翻&quot;">​</a></h2><div class="danger custom-block"><p class="custom-block-title">这条规则比看起来重要得多</p><p>游戏内有些英文<strong>看起来像文本，实际是代码的「钥匙」</strong>。翻了会导致功能失效。</p><p>框架文档与汉化都遵守这条：<strong>按名字匹配的字符串，一律不翻。</strong></p></div><h3 id="不能翻的类型" tabindex="-1">不能翻的类型 <a class="header-anchor" href="#不能翻的类型" aria-label="Permalink to &quot;不能翻的类型&quot;">​</a></h3><table tabindex="0"><thead><tr><th>类型</th><th>例子</th><th>翻了会怎样</th></tr></thead><tbody><tr><td><strong>对象名</strong></td><td>GameObject 的 <code>name</code></td><td><code>Find()</code> 找不到对象，功能失效</td></tr><tr><td><strong>行动档位</strong></td><td><code>No Action</code> / <code>Diving</code> / <code>Surface</code> / <code>Firing</code> / <code>Dive</code></td><td>代码按名匹配，翻了档位失效</td></tr><tr><td><strong>时段关键字</strong></td><td><code>Noon</code> / <code>Dawn</code> / <code>Dusk</code> / <code>Night</code></td><td>编队定义里写这些值，翻了识别不了</td></tr><tr><td><strong>舰种代号</strong></td><td><code>BB</code> / <code>CA</code> / <code>DD</code> / <code>SS</code></td><td>分类逻辑失效</td></tr></tbody></table><h3 id="为什么「看着像文本」却是「钥匙」" tabindex="-1">为什么「看着像文本」却是「钥匙」 <a class="header-anchor" href="#为什么「看着像文本」却是「钥匙」" aria-label="Permalink to &quot;为什么「看着像文本」却是「钥匙」&quot;">​</a></h3><p>一个字符串在代码里可能承担<strong>两种角色</strong>：</p><table tabindex="0"><thead><tr><th>角色</th><th>能不能翻</th><th>例子</th></tr></thead><tbody><tr><td><strong>查找键</strong></td><td>❌ 不能</td><td><code>Find(&quot;No Action&quot;)</code> —— 翻了就找不到</td></tr><tr><td><strong>显示文本</strong></td><td>✅ 能</td><td><code>label.Text = &quot;No Action&quot;</code> —— 翻了玩家就能看懂</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">判断方法</p><p>看这个字符串<strong>被怎么用</strong>：</p><ul><li>如果它出现在 <code>Find()</code> / <code>BringIn()</code> / <code>.name ==</code> 这类<strong>比较或查找</strong>的位置 → <strong>不能翻</strong></li><li>如果它出现在 <code>xxx.Text = </code> 这类<strong>赋值显示</strong>的位置 → <strong>能翻</strong></li></ul><p><strong>一刀切（要么全翻要么全不翻）必然两头错。</strong></p></div><h2 id="给-mod-作者的提醒" tabindex="-1">给 Mod 作者的提醒 <a class="header-anchor" href="#给-mod-作者的提醒" aria-label="Permalink to &quot;给 Mod 作者的提醒&quot;">​</a></h2><div class="warning custom-block"><p class="custom-block-title">你在 mod.json 里写的值也要遵守这个规则</p><p>比如编队定义里的 <code>timeOfDay</code>，<strong>必须用英文原值</strong>：</p><div class="language-json vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;timeOfDay&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;Dawn&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">     ✅ 正确</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;timeOfDay&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;黎明&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">      ❌ 识别不了</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p>同理，<code>type</code> 字段必须用代号（<code>CA</code>、<code>DD</code>…），不能写中文。</p></div><p>详细的关键字清单见 <a href="/AtlanticFleetSite/docs/dev/param-keys">参数键全表</a> 里的「保留字」部分。</p><h2 id="术语对照" tabindex="-1">术语对照 <a class="header-anchor" href="#术语对照" aria-label="Permalink to &quot;术语对照&quot;">​</a></h2><p>汉化使用的标准术语（如果你在这些地方看到不同翻译，以本表为准）：</p><table tabindex="0"><thead><tr><th>英文</th><th>标准译法</th></tr></thead><tbody><tr><td>Hedgehog</td><td>刺猬弹</td></tr><tr><td>Squid</td><td>乌贼炮</td></tr><tr><td>Anti-Submarine Warfare</td><td>反潜作战</td></tr><tr><td>Ship Maneuver</td><td>舰船机动</td></tr><tr><td>Carrier Aircraft</td><td>舰载机</td></tr><tr><td>Renown</td><td>威望 / 威望</td></tr><tr><td>Bellwort</td><td>垂铃草</td></tr><tr><td>Marigold</td><td>万寿菊</td></tr></tbody></table><p>完整术语表见 <a href="/AtlanticFleetSite/docs/glossary">术语表</a>。</p><h2 id="相关" tabindex="-1">相关 <a class="header-anchor" href="#相关" aria-label="Permalink to &quot;相关&quot;">​</a></h2><ul><li>完整术语表 → <a href="/AtlanticFleetSite/docs/glossary">术语表</a></li><li>汉化技术细节 → <a href="/AtlanticFleetSite/docs/technical">技术细节</a></li><li>参数键的保留字 → <a href="/AtlanticFleetSite/docs/dev/param-keys">参数键全表</a></li></ul>`,29)])])}const b=d(r,[["render",s]]);export{g as __pageData,b as default};
